CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, first_name TEXT NOT NULL DEFAULT '', timezone TEXT NOT NULL DEFAULT 'Europe/Chisinau', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS settings (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, semester_start TEXT, first_week_parity TEXT CHECK(first_week_parity IN ('even','odd')), english_duration INTEGER CHECK(english_duration BETWEEN 1 AND 240), sleep_hours REAL NOT NULL DEFAULT 8, sleep_latency INTEGER NOT NULL DEFAULT 15, wash_minutes INTEGER NOT NULL DEFAULT 15, breakfast_minutes INTEGER NOT NULL DEFAULT 20, get_ready_minutes INTEGER NOT NULL DEFAULT 15, travel_buffer INTEGER NOT NULL DEFAULT 10, home_address TEXT DEFAULT 'strada Tudor Strișcă 8/7, Chișinău', university_address TEXT DEFAULT 'strada Alexei Mateevici 60, Chișinău', theme TEXT NOT NULL DEFAULT 'light' CHECK(theme IN ('light','dark')), reminders_enabled INTEGER NOT NULL DEFAULT 0, reminder_minutes INTEGER NOT NULL DEFAULT 60, wake_reminder INTEGER NOT NULL DEFAULT 0, sleep_reminder INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS homework (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, subject TEXT, due_at TEXT, due_date TEXT, note TEXT, completed INTEGER NOT NULL DEFAULT 0, telegram_reminder INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS homework_user_due ON homework(user_id,due_at) WHERE completed=0;
CREATE TABLE IF NOT EXISTS notification_log (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, event_key TEXT NOT NULL, sent_at TEXT, attempts INTEGER NOT NULL DEFAULT 0, next_attempt TEXT, UNIQUE(user_id,event_key));
CREATE TABLE IF NOT EXISTS schedule_overrides (id TEXT PRIMARY KEY, user_id TEXT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, schedule TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS transit_state (id INTEGER PRIMARY KEY CHECK(id=1), available INTEGER NOT NULL, source TEXT NOT NULL, checked_at TEXT NOT NULL, note TEXT NOT NULL, estimate_minutes INTEGER NOT NULL, vehicle_count INTEGER);
